import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../../',import.meta.url));
export const longJumpManifest=()=>JSON.parse(readFileSync(new URL('../../docs/long-jump-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const blob=bytes=>createHash('sha1').update(Buffer.concat([Buffer.from('blob '+bytes.length+'\0'),bytes])).digest('hex');
export function reverseLongJump(path,bytes,manifest=longJumpManifest()){
 const f=manifest.files.find(f=>f.path===path);if(!f||f.beforeText===undefined)return Buffer.from(bytes);
 assert.equal(hash(bytes),f.sha256,path+' Long Jump current bytes');assert.equal(blob(bytes),f.gitBlob,path+' Long Jump current Git blob');
 const before=Buffer.from(f.beforeText);assert.equal(hash(before),f.beforeSha256,path+' Long Jump prior bytes');assert.equal(blob(before),f.beforeGitBlob,path+' Long Jump prior Git blob');return before;
}
export function readBeforeLongJump(file,encoding){
 const absolute=file instanceof URL?fileURLToPath(file):path.resolve(file),relative=path.relative(root,absolute).split(path.sep).join('/');
 const bytes=reverseLongJump(relative,readFileSync(file));return encoding?bytes.toString(encoding):bytes;
}

import test from'node:test';import assert from'node:assert/strict';import{readFileSync,existsSync}from'node:fs';import{mkdtemp,mkdir,writeFile,rm}from'node:fs/promises';import{tmpdir}from'node:os';import path from'node:path';import{catalog}from'../src/catalog.mjs';
const read=p=>readFileSync(new URL('../'+p,import.meta.url),'utf8');
test('production catalog contains only original Jump plus Hurdles and retains original P favicon',()=>{assert.deepEqual(catalog.games.map(g=>g.id),['long-jump','hurdles']);assert.deepEqual(catalog.minigames.map(g=>g.id),['reaction-rod']);assert.deepEqual(catalog.externalGames.map(e=>e.id),['taiwanfighter']);assert.deepEqual(catalog.platforms,[]);assert.match(read('src/render.mjs'),/app-icons\/platform/);assert.ok(existsSync(new URL('../public/assets/favicon.svg',import.meta.url)));});
test('artifact guard rejects another game even when it has no catalog card',async()=>{const{assertReleasedGames}=await import('../scripts/release-policy.mjs');const root=await mkdtemp(path.join(tmpdir(),'pf-main-release-'));try{for(const game of['long-jump','hurdles','reaction-rod']){await mkdir(path.join(root,'games',game),{recursive:true});await writeFile(path.join(root,'games',game,'index.html'),'<title>game</title>');}await assertReleasedGames(root);await mkdir(path.join(root,'games','shot-put'));await writeFile(path.join(root,'games','shot-put','index.html'),'<title>unreleased</title>');await assert.rejects(assertReleasedGames(root),/Unapproved game directory/);}finally{await rm(root,{recursive:true,force:true});}});
test('actual public game artifact policy and hurdle dependencies are complete',async()=>{const{assertReleasedGames}=await import('../scripts/release-policy.mjs');await assertReleasedGames(new URL('../public/',import.meta.url));for(const name of['bgm','step','jump','flight','land','result'])for(const ext of['ogg','mp3'])assert.ok(existsSync(new URL('../public/games/hurdles/audio/'+name+'.'+ext,import.meta.url)));const manifest=JSON.parse(read('public/games/hurdles/manifest.webmanifest'));assert.equal(manifest.scope,'./');for(const icon of manifest.icons)assert.ok(existsSync(new URL(icon.src,new URL('../public/games/hurdles/',import.meta.url))));assert.match(read('wrangler.jsonc'),/"not_found_handling": "404-page"/);});
test('artifact guard rejects extra HTML inside shared and unapproved files outside games',async()=>{const{assertReleasedGames,assertProductionInventory}=await import('../scripts/release-policy.mjs');const root=await mkdtemp(path.join(tmpdir(),'pf-extra-'));try{for(const id of['long-jump','hurdles','reaction-rod','shared'])await mkdir(path.join(root,'games',id),{recursive:true});for(const id of['long-jump','hurdles','reaction-rod'])await writeFile(path.join(root,'games',id,'index.html'),'game');await writeFile(path.join(root,'games/shared/index.html'),'unreleased');await assert.rejects(assertReleasedGames(root),/Unapproved game HTML/);await rm(path.join(root,'games/shared/index.html'));await assertProductionInventory(root,['games/long-jump/index.html','games/hurdles/index.html','games/reaction-rod/index.html']);await writeFile(path.join(root,'secret-game.html'),'game');await assert.rejects(assertProductionInventory(root,['games/long-jump/index.html','games/hurdles/index.html','games/reaction-rod/index.html']),/Unapproved production file/);}finally{await rm(root,{recursive:true,force:true});}});

import {tmpdir} from 'node:os';import path from 'node:path';import {pathToFileURL} from 'node:url';import {readExternalCatalog} from '../src/external-catalog.mjs';
import test from 'node:test';import assert from 'node:assert/strict';import{readFileSync,mkdtempSync,writeFileSync,rmSync}from'node:fs';import{JSDOM}from'jsdom';import{catalog}from'../src/catalog.mjs';import{renderPage}from'../src/render.mjs';
