test('fighter production flag and exact destination are admission boundaries',()=>{const entry=catalog.externalGames?.[0];assert.ok(entry);assert.equal(new JSDOM(renderPage({...catalog,externalGames:[{...entry,release:{preview:true,production:false}}]})).window.document.querySelector('[data-external-id]'),null);for(const patch of [{href:'https://evil.test/'},{id:'other'},{image:'/assets/other.png'}])assert.throws(()=>renderPage({...catalog,externalGames:[{...entry,...patch}]}));});
